export function getLessonContent(id: string, title: string, subject: string): DetailedLessonContent {
  if (DETAILED_LESSONS[id]) {
    return DETAILED_LESSONS[id];
  }

  // Generic fallback generator with Unicode text formula structures
  return {
    id,
    averageQuestions: '1–2 questions per year',
    whatYoullLearn: [
      `Key concepts and definitions of ${title}`,
      `Practical applications in IAT exams`,
      `Formula derivations and quick problem-solving techniques`,
      `Important exceptions and core rules`
    ],
    concepts: [
      {
        title: `Core Concept of ${title}`,
        explanation: `This establishes the primary theoretical base of ${title}. Read definitions carefully before proceeding.`,
        example: `Applying the base rules of ${title} to standard textbook problems.`,
        trap: `Ensure you don't skip checking base conditions or dimensions before writing the final output.`
      },
      {
        title: `Secondary Theory of ${title}`,
        explanation: `Links this chapter with adjacent units in the ${subject} syllabus.`,
        example: `Combining variables to solve composite questions.`,
        trap: `Do not confuse formulas when moving between different subtopics.`
      }
    ],
    formulas: [
      'Relationship: Y = mX + C',
      'Rate/Efficiency: Δ = Output / Input',
      'Net Effect: Total = A + B - C'
    ],
    examTraps: [
      {
        trap: 'Calculation Speed vs. Accuracy',
        warning: 'Double-check calculations. Skipping arithmetic verification is where most students lose marks in simple questions.'
      }
    ],
    questionPattern: [
      `Fundamental qualitative definition queries from ${title}`,
      'Direct formula substitution problems',
      'Determining dependencies using proportionality graphs'
    ],
    quizQuestions: [
      {
        id: `${id}-q1`,
        topicId: 'core-definitions',
        difficulty: 'easy' as const,
        estimatedTimeSeconds: 45,
        question: `Which of the following best describes the main focus of ${title}?`,
        options: ['Basic definitions and principles', 'Advanced theoretical research', 'Complex calculations only', 'None of the above'],
        correctAnswerIndex: 0,
        explanation: 'This chapter focuses on establishing clear, basic conceptual foundations and core IAT principles.'
      },
      {
        id: `${id}-q2`,
        topicId: 'units-and-dimensions',
        difficulty: 'easy' as const,
        estimatedTimeSeconds: 45,
        question: 'What is the most critical factor to check while solving numerical problems in this chapter?',
        options: ['Handwriting neatness', 'Consistency of units', 'Speed of writing', 'Using multiple methods'],
        correctAnswerIndex: 1,
        explanation: 'Inconsistent units (e.g. mixing SI and non-SI values) are the most common source of error in numerical questions.'
      },
      {
        id: `${id}-q3`,
        topicId: 'ncert-fundamentals',
        difficulty: 'easy' as const,
        estimatedTimeSeconds: 45,
        question: 'Why is NCERT reading highly recommended for this topic?',
        options: ['It contains exact exam questions', 'It covers the core concepts in detail', 'It has colored illustrations', 'It is the shortest book'],
        correctAnswerIndex: 1,
        explanation: 'IISER Aptitude Test relies heavily on deep conceptual statements that are built directly from NCERT foundations.'
      },
      {
        id: `${id}-q4`,
        topicId: 'problem-solving-approach',
        difficulty: 'easy' as const,
        estimatedTimeSeconds: 45,
        question: 'What is the first step in solving a multi-step problem in this chapter?',
        options: ['Guessing the answer', 'Listing down known variables', 'Writing a long paragraph', 'Skipping to the next question'],
        correctAnswerIndex: 1,
        explanation: 'Listing down given variables and identifying what needs to be found is the cleanest way to solve multi-step problems.'
      },
      {
        id: `${id}-q5`,
        topicId: 'revision-strategy',
        difficulty: 'easy' as const,
        estimatedTimeSeconds: 45,
        question: 'How should you approach revision for this chapter?',
        options: ['Re-reading the entire textbook', 'Reviewing formula sheets and PYQ patterns', 'Doing no revision', 'Watching long lectures'],
        correctAnswerIndex: 1,
        explanation: 'Short formula reviews and analyzing pyq patterns is the highest efficiency revision strategy.'
      }
    ]
  };
}
